pub(crate) fn render(dev_reload: &str) -> String {
    r#"<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RustDL Activity Center</title><style>
:root{color-scheme:dark;font-family:Inter,ui-sans-serif,system-ui,sans-serif}*{box-sizing:border-box}body{min-height:100vh;margin:0;padding:clamp(1rem,4vw,3rem);color:#f7f7f8;background:radial-gradient(circle at 12% 0,#273166,transparent 32rem),radial-gradient(circle at 100% 90%,#173e3a,transparent 28rem),#090a0f}main{width:min(100%,900px);margin:auto}.top{display:flex;align-items:end;justify-content:space-between;gap:1rem;margin-bottom:1rem}.eyebrow{color:#8fe3d2;font-size:.7rem;font-weight:850;letter-spacing:.12em;text-transform:uppercase}h1{margin:.35rem 0;font-size:clamp(2.35rem,8vw,4.4rem);letter-spacing:-.055em}p{margin:0;color:#929aab;line-height:1.5}a,button{min-height:2.65rem;padding:.65rem .8rem;border:1px solid #ffffff24;border-radius:11px;color:#dfe5ef;background:#ffffff0a;text-decoration:none;font:800 .76rem/1.2 system-ui;cursor:pointer}.toolbar{display:flex;align-items:center;justify-content:space-between;gap:.7rem;margin-bottom:.75rem;padding:.7rem;border:1px solid #ffffff18;border-radius:15px;background:#10121ade}.live{display:flex;align-items:center;gap:.45rem;color:#8fe3d2;font-size:.72rem;font-weight:850}.live::before{content:"";width:.48rem;height:.48rem;border-radius:50%;background:currentColor;box-shadow:0 0 0 .28rem #70dfc918}.live.error{color:#ffaaa5}.filters{display:flex;gap:.45rem;overflow:auto;padding:.15rem 0 .8rem;scrollbar-width:none}.filters button{white-space:nowrap}.filters button.active{border-color:#70dfc966;color:#07110f;background:#70dfc9}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:.65rem;margin-bottom:.8rem}.metric{padding:.9rem;border:1px solid #ffffff18;border-radius:16px;background:#11131bde}.metric strong,.metric span{display:block}.metric strong{font-size:clamp(1.35rem,5vw,2rem);font-variant-numeric:tabular-nums}.metric span{margin-top:.2rem;color:#7f8798;font-size:.68rem}.feed{display:grid;gap:.65rem}.item{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:.8rem;padding:.9rem;border:1px solid #ffffff18;border-radius:17px;background:linear-gradient(145deg,#151821e8,#0d0f16ee)}.icon{display:grid;place-items:center;width:2.5rem;height:2.5rem;border-radius:12px;color:#07110f;background:#70dfc9;font-weight:950}.item.issue .icon{background:#ff9f91}.item.complete .icon{background:#8490a8}.copy{min-width:0}.copy strong,.copy span{display:block}.copy strong{overflow:hidden;font-size:.83rem;text-overflow:ellipsis;white-space:nowrap}.copy span{margin-top:.25rem;color:#7f8798;font-size:.7rem;line-height:1.4}.progress{height:3px;margin-top:.55rem;overflow:hidden;border-radius:99px;background:#ffffff16}.progress i{display:block;height:100%;border-radius:inherit;background:#70dfc9}.item>a{white-space:nowrap}.empty{padding:2rem;border:1px dashed #ffffff24;border-radius:17px;color:#7f8798;text-align:center}.system{margin-top:.8rem;padding:1rem;border:1px solid #ffffff18;border-radius:17px;background:#11131bde}.system h2{margin:0 0 .75rem;font-size:.82rem}.system-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.55rem}.system-row{padding:.7rem;border-radius:11px;background:#090b11}.system-row strong,.system-row span{display:block}.system-row strong{font-size:.72rem}.system-row span{margin-top:.25rem;color:#7f8798;font-size:.68rem}.warning{color:#ffd08a!important}.hidden{display:none!important}@media(max-width:650px){.top,.toolbar{align-items:stretch;flex-direction:column}.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.item{grid-template-columns:auto minmax(0,1fr)}.item>a{grid-column:1/-1;text-align:center}.system-grid{grid-template-columns:1fr}}@media(prefers-reduced-motion:reduce){*{transition-duration:.01ms!important}}
</style></head><body><main><div class="top"><div><span class="eyebrow">Live background work</span><h1>Activity.</h1><p>Downloads, transfers, storage pressure, and app updates in one place.</p></div><a href="/">← Gallery</a></div><div class="toolbar"><span id="live" class="live">Connecting</span><button id="refresh" type="button">Refresh</button></div><div class="filters" role="group" aria-label="Activity filters"><button class="active" data-filter="all">All</button><button data-filter="active">Active</button><button data-filter="issue">Needs attention</button><button data-filter="complete">Completed</button></div><section class="metrics"><div class="metric"><strong id="active-count">0</strong><span>Active operations</span></div><div class="metric"><strong id="issue-count">0</strong><span>Need attention</span></div><div class="metric"><strong id="complete-count">0</strong><span>Completed</span></div><div class="metric"><strong id="free-space">—</strong><span>Storage available</span></div></section><section id="feed" class="feed" aria-live="polite"></section><section class="system"><h2>System services</h2><div class="system-grid"><div class="system-row"><strong>Download policy</strong><span id="policy">Reading…</span></div><div class="system-row"><strong>App updates</strong><span id="updates">Reading…</span></div><div class="system-row"><strong>Thermal state</strong><span id="thermal">Reading…</span></div><div class="system-row"><strong>Network</strong><span id="network">Reading…</span></div></div></section></main><script>
(()=>{'use strict';const native=window.RustDLActivity,feed=document.querySelector('#feed'),live=document.querySelector('#live'),refreshButton=document.querySelector('#refresh'),filters=[...document.querySelectorAll('[data-filter]')];let currentFilter='all',pending=false,last=null;const bytes=value=>{if(value==null)return "—";value=Number(value||0);const units=['B','KB','MB','GB','TB'];let unit=0;while(value>=1024&&unit<units.length-1){value/=1024;unit++}return value.toFixed(unit>1?1:0)+' '+units[unit]},label=value=>({queued:'Queued',starting:'Starting',downloading:'Downloading',paused:'Paused',ready:'Completed',failed:'Failed',cancelled:'Cancelled',hashing:'Preparing',sending:'Sending'}[value]||value),category=phase=>['failed','paused'].includes(phase)?'issue':['ready','cancelled'].includes(phase)?'complete':'active';
const row=(item,type)=>{const kind=category(item.phase),article=document.createElement('article');article.className='item '+kind;article.dataset.category=kind;const icon=document.createElement('span');icon.className='icon';icon.textContent=type==='transfer'?'⇄':kind==='active'?'↓':kind==='issue'?'!':'✓';const copy=document.createElement('div');copy.className='copy';const title=document.createElement('strong');title.textContent=item.filename;const detail=document.createElement('span');const done=Number(type==='transfer'?item.sent:item.downloaded||0),total=Number(item.total||0);detail.textContent=label(item.phase)+' · '+bytes(done)+(total?' / '+bytes(total):'')+(item.error?' · '+item.error:'');copy.append(title,detail);if(kind==='active'){const progress=document.createElement('div');progress.className='progress';const bar=document.createElement('i');bar.style.width=(total?Math.min(100,done/total*100):0)+'%';progress.append(bar);copy.append(progress)}const link=document.createElement('a');link.href=type==='transfer'?'/peers':item.phase==='ready'?'/watch/'+encodeURIComponent(item.filename):'/queue';link.textContent=type==='transfer'?'Transfer':item.phase==='ready'?'Play':'Queue';article.append(icon,copy,link);return article};
const applyFilter=()=>{feed.querySelectorAll('.item').forEach(item=>item.classList.toggle('hidden',currentFilter!=='all'&&item.dataset.category!==currentFilter));const visible=feed.querySelectorAll('.item:not(.hidden)').length;let empty=feed.querySelector('.empty');if(!visible){if(!empty){empty=document.createElement('div');empty.className='empty';feed.append(empty)}empty.textContent=currentFilter==='all'?'No recorded activity yet.':'No activity matches this filter.'}else empty?.remove()};
const render=(state,nativeState)=>{last=state;feed.replaceChildren();const items=[...(state.downloads||[]).map(item=>[item,'download']),...(state.transfers||[]).map(item=>[item,'transfer'])];items.forEach(([item,type])=>feed.append(row(item,type)));document.querySelector('#active-count').textContent=state.counts?.active||0;document.querySelector('#issue-count').textContent=state.counts?.issues||0;document.querySelector('#complete-count').textContent=state.counts?.completed||0;document.querySelector('#free-space').textContent=bytes(state.system?.freeBytes);document.querySelector('#free-space').classList.toggle('warning',!!state.system?.storageLow);document.querySelector('#policy').textContent=state.system?.powerSave?'Battery saver · reduced concurrency':state.system?.charging?'Charging · performance enabled':'Balanced';document.querySelector('#thermal').textContent=['Normal','Light','Moderate','Severe','Critical','Emergency','Shutdown'][Number(state.system?.thermalStatus||0)]||'Unknown';document.querySelector('#network').textContent=state.system?.unmetered?'Unmetered':'Metered or unknown';const update=nativeState?.update;document.querySelector('#updates').textContent=update?.detail||'Status unavailable';applyFilter();live.textContent='Live · updated '+new Date().toLocaleTimeString();live.classList.remove('error')};
const refresh=()=>{if(pending)return;pending=true;refreshButton.disabled=true;Promise.all([fetch('/__app/activity.json',{cache:'no-store'}).then(response=>response.ok?response.json():Promise.reject()),Promise.resolve().then(()=>native?JSON.parse(native.status()):null)]).then(([state,nativeState])=>render(state,nativeState)).catch(()=>{live.textContent='Could not refresh · tap Refresh';live.classList.add('error')}).finally(()=>{pending=false;refreshButton.disabled=false})};filters.forEach(button=>button.addEventListener('click',()=>{currentFilter=button.dataset.filter;filters.forEach(item=>item.classList.toggle('active',item===button));applyFilter()}));refreshButton.addEventListener('click',refresh);addEventListener('rustdl:state',event=>{if(['queue','peer','update','activity','sync'].includes(event.detail?.type))refresh()});document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh()});refresh();setInterval(()=>{if(!document.hidden)refresh()},15000)})();
</script><!--DEV_RELOAD--></body></html>"#.replace("<!--DEV_RELOAD-->", dev_reload)
}
